cat > /tmp/test_mapping_bool.py << 'EOF'
# Test what happens with a mapping when __len__ returns negative
class TestMapping:
    def __init__(self, len_val):
        self.len_val = len_val

    def __len__(self):
        return self.len_val

    def __iter__(self):
        return iter([])

    def __getitem__(self, key):
        raise KeyError(key)

    def __contains__(self, key):
        return False

# Test with negative length
m = TestMapping(-1)
try:
    print(f"len(m) = {len(m)}")
    if m:
        print("mapping is truthy")
    else:
        print("mapping is falsy")
except Exception as e:
    print(f"Error: {e}")

# Test with zero
m = TestMapping(0)
try:
    print(f"\nlen(m) = {len(m)}")
    if m:
        print("mapping is truthy")
    else:
        print("mapping is falsy")
except Exception as e:
    print(f"Error: {e}")
EOF
python /tmp/test_mapping_bool.py

